}
New-AzNetworkFabricInternalNetwork -Name $name -L3IsolationDomainName $l3domainName -ResourceGroupName $resourceGroupName -VlanId "701" -BgpConfigurationPeerAsn 65047 -BgpConfigurationAllowAs 2 -BgpConfigurationAllowAsOverride "Enable" -BgpConfigurationDefaultRouteOriginate "True" -BgpConfigurationIpv4ListenRangePrefix @("20.10.10.2/28") -BgpConfigurationIpv4NeighborAddress @(@{Address = "20.10.10.2"}) -ConnectedIPv4Subnet $connectedIPv4Subnet -EgressAclId "/subscriptions/subscriptionId/resourceGroups/example-rg/providers/Microsoft.ManagedNetworkFabric/accessControlLists/aclName" -ExportRoutePolicy $exportRoutePolicy -Extension "NoExtension" -ImportRoutePolicy $importRoutePolicy -IngressAclId "/subscriptions/subscriptionId/resourceGroups/example-rg/providers/Microsoft.ManagedNetworkFabric/accessControlLists/aclName" -IsMonitoringEnabled "True" -Mtu 1500 -StaticRouteConfiguration @{Ipv4Route = @(@{NextHop = @("10.0.0.1"); Prefix = "10.1.0.0/24"})}

$connectedSubnetRoutePolicy = @{
    ExportRoutePolicy = @(@{
        ExportIpv4RoutePolicyId = "/subscriptions/9531faa8-8c39-4165-b033-48697fe943db/resourceGroups/nfa-tool-ts-powershell-rg092123/providers/Microsoft.ManagedNetworkFabric/routePolicies/RoutePolicyName"
        ExportIpv6RoutePolicyId = "/subscriptions/9531faa8-8c39-4165-b033-48697fe943db/resourceGroups/nfa-tool-ts-powershell-rg092123/providers/Microsoft.ManagedNetworkFabric/routePolicies/RoutePolicyName"
    })
}
$aggregateRouteConfiguration = @{
    Ipv4Route = @(@{
        Prefix = "10.0.0.1/28"
    })
    Ipv6Route = @(@{
        Prefix = "2fff::/64"
    })
}

New-AzNetworkFabricL3Domain -Name $name -ResourceGroupName $resourceGroupName -Location $location -NetworkFabricId $nfId -AggregateRouteConfiguration $aggregateRouteConfiguration -RedistributeConnectedSubnet "True" -RedistributeStaticRoute "True" -ConnectedSubnetRoutePolicy $connectedSubnetRoutePolicy

$layer2Configuration = @{
    Interface = @("/subscriptions//resourceGroups/example-rg/providers/Microsoft.ManagedNetworkFabric/networkFabrics/example-fabric/networkToNetworkInterconnects/example-interface")
    Mtu = 1500
}
$importRoutePolicy = @{
    ImportIpv4RoutePolicyId = $global:config.nni.importIpv4RoutePolicyId
    ImportIpv6RoutePolicyId = $global:config.nni.importIpv6RoutePolicyId
}
$exportRoutePolicy = @{
    ExportIpv4RoutePolicyId = $global:config.nni.exportIpv4RoutePolicyId
    ExportIpv6RoutePolicyId = $global:config.nni.exportIpv6RoutePolicyId
}

New-AzNetworkFabricNni -Name $name -NetworkFabricName $nfName -ResourceGroupName $resourceGroupName -UseOptionB "True" -IsManagementType "True" -Layer2Configuration $layer2Configuration -NniType "CE" -OptionBLayer3ConfigurationPeerAsn 28 -OptionBLayer3ConfigurationPrimaryIpv4Prefix "172.31.0.0/31" -OptionBLayer3ConfigurationSecondaryIpv4Prefix "172.31.0.20/31" -OptionBLayer3ConfigurationVlanId 501 -ExportRoutePolicy $ExportRoutePolicy -ImportRoutePolicy $importRoutePolicy
